namespace JetDatabaseWriter.Tests.Encryption;

using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.ExceptionServices;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using JetDatabaseWriter.Encryption;
using JetDatabaseWriter.Exceptions;
using JetDatabaseWriter.Transactions;
using JetDatabaseWriter.Verification;
using Xunit;

/// <summary>Connects generated byte checks and acquisition progress to actual replacement evidence.</summary>
public sealed class ReplacementFieldConformanceTests
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    /// <summary>Every checked byte is significant; reserved bytes retain checksum-only treatment.</summary>
    [Fact]
    public void HeaderByteChecks_EveryPosition_MatchesDeclaredFields()
    {
        byte[] header = new byte[256];
        Encoding.ASCII.GetBytes("JDWREPL1").CopyTo(header, 0);
        BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(8), 1);
        BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(12), 256);
        byte[] identity = Enumerable.Range(0, 32).Select(static index => checked((byte)(index + 1))).ToArray();
        byte[] digest = Enumerable.Range(0, 32).Select(static index => checked((byte)(index + 65))).ToArray();
        identity.CopyTo(header, 32);
        digest.CopyTo(header, 224);
        for (uint index = 0; index < header.Length; index++)
        {
            byte pathByte = identity[index % 32];
            byte digestByte = digest[index % 32];
            Assert.True(RecoveryKernel.ReplacementHeaderByteValid(index, header[index], pathByte, digestByte));
            bool checkedByte = index is < 16 or (>= 32 and < 64) or >= 224;
            Assert.Equal(!checkedByte, RecoveryKernel.ReplacementHeaderByteValid(index, (byte)(header[index] ^ 255), pathByte, digestByte));
        }

        Assert.False(RecoveryKernel.ReplacementHeaderByteValid(256, 0, 0, 0));
        Assert.False(RecoveryKernel.ReplacementHeaderByteValid(uint.MaxValue, 0, 0, 0));
        for (uint position = 0; position < 256; position++)
        {
            Assert.Equal(position is >= 16 and < 32, RecoveryKernel.ReplacementGenerationByte(false, position, 1));
            Assert.False(RecoveryKernel.ReplacementGenerationByte(false, position, 0));
            Assert.True(RecoveryKernel.ReplacementGenerationByte(true, position, 0));
        }
    }

    /// <summary>Complete decisions bind every generation, selected-image and checksum byte.</summary>
    [Fact]
    public void DecisionByteChecks_EveryPosition_MatchesDeclaredFields()
    {
        byte[] decision = new byte[96];
        Encoding.ASCII.GetBytes("JDWCMT01").CopyTo(decision, 0);
        for (uint index = 8; index < decision.Length; index++)
        {
            decision[index] = checked((byte)index);
        }

        for (uint index = 0; index < decision.Length; index++)
        {
            byte value = decision[index];
            Assert.True(RecoveryKernel.ReplacementDecisionByteValid(index, value, value, value, value));
            Assert.Equal(index is >= 56 and < 64, RecoveryKernel.ReplacementDecisionByteValid(index, (byte)(value ^ 255), value, value, value));
        }

        Assert.False(RecoveryKernel.ReplacementDecisionByteValid(96, 0, 0, 0, 0));
        Assert.False(RecoveryKernel.ReplacementDecisionByteValid(uint.MaxValue, 0, 0, 0, 0));
    }

    /// <summary>Every positive bounded read advances exactly; EOF and invalid counts refuse.</summary>
    [Fact]
    public void EvidenceReadCursor_EveryReadSize_ProgressesOrRefuses()
    {
        foreach (uint length in new uint[] { 96, 256 })
        {
            for (uint offset = 0; offset < length; offset++)
            {
                Assert.Equal(353u, RecoveryKernel.ReplacementReadAdvance(length, offset, 0));
                for (uint count = 1; count <= length - offset; count++)
                {
                    uint next = RecoveryKernel.ReplacementReadAdvance(length, offset, count);
                    Assert.Equal(offset + count, next);
                    Assert.True(length - next < length - offset);
                }

                Assert.Equal(353u, RecoveryKernel.ReplacementReadAdvance(length, offset, length - offset + 1));
            }

            Assert.Equal(353u, RecoveryKernel.ReplacementReadAdvance(length, length, 1));
        }

        Assert.Equal(353u, RecoveryKernel.ReplacementReadAdvance(uint.MaxValue, 0, 1));
        Assert.Equal(353u, RecoveryKernel.ReplacementReadAdvance(256, uint.MaxValue, uint.MaxValue));
    }

    /// <summary>Short reads consume the exact fixed record without borrowing bytes from the following record.</summary>
    /// <param name="length">The acquired record size.</param>
    /// <param name="maximumRead">The largest successful read.</param>
    [Theory]
    [InlineData(96, 1)]
    [InlineData(96, 17)]
    [InlineData(256, 1)]
    [InlineData(256, 37)]
    public void EvidenceAcquisition_ShortReads_ConsumesExactly(int length, int maximumRead)
    {
        byte[] bytes = Enumerable.Range(0, length + 13).Select(static index => (byte)(index % 251)).ToArray();
        using var directory = new EvidenceDirectory();
        File.WriteAllBytes(directory.Path, bytes);
        using var input = new ObservedEvidence(directory.Path, maximumRead);
        byte[] actual = new byte[length];
        ReadEvidence(input, actual);
        Assert.Equal(bytes[..length], actual);
        Assert.Equal(length, input.Position);
        Assert.True(input.ReadCalls > 1);
    }

    /// <summary>Incomplete reads and real I/O errors terminate without being classified as admitted evidence.</summary>
    /// <param name="failure">The interruption returned by the stream.</param>
    [Theory]
    [InlineData("eof")]
    [InlineData("io")]
    public void EvidenceAcquisition_InterruptedRead_Refuses(string failure)
    {
        using var directory = new EvidenceDirectory();
        File.WriteAllBytes(directory.Path, new byte[256]);
        using var input = new ObservedEvidence(directory.Path, 7, stopAfter: 37, failure);
        if (failure == "io")
        {
            Assert.Throws<IOException>(() => ReadEvidence(input, new byte[256]));
        }
        else
        {
            Assert.Throws<JetCorruptDataException>(() => ReadEvidence(input, new byte[256]));
        }

        Assert.Equal(37, input.Position);
    }

    /// <summary>Checksum-valid field conflicts refuse before acquiring or provisioning generation ownership.</summary>
    /// <param name="offset">The semantic field byte to contradict.</param>
    [Theory]
    [InlineData(0)]
    [InlineData(8)]
    [InlineData(12)]
    [InlineData(32)]
    [InlineData(63)]
    [InlineData(224)]
    [InlineData(256)]
    [InlineData(264)]
    [InlineData(279)]
    [InlineData(280)]
    [InlineData(311)]
    [InlineData(320)]
    public Task FieldConflict_RefusesBeforeOwnershipBootstrap(int offset) => CheckFieldConflictAsync(offset, retainOwnership: false);

    /// <summary>Invalid fields retain already validated native and receipt generations byte for byte.</summary>
    /// <param name="offset">The header or decision byte to contradict.</param>
    [Theory]
    [InlineData(63)]
    [InlineData(264)]
    public Task FieldConflict_PreservesExistingOwnership(int offset) => CheckFieldConflictAsync(offset, retainOwnership: true);

    /// <summary>The generated array loops reject malformed lengths and exactly bind every byte of their inputs.</summary>
    [Fact]
    public void CompleteArrayChecks_BindFieldsAndRefuseWrongSizes()
    {
        byte[] header = new byte[256];
        Encoding.ASCII.GetBytes("JDWREPL1").CopyTo(header, 0);
        BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(8), 1);
        BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(12), 256);
        header[31] = 1;
        byte[] identity = new byte[32];
        byte[] headerHash = SHA256.HashData(header.AsSpan(0, 224));
        headerHash.CopyTo(header, 224);
        byte[] decision = new byte[96];
        Encoding.ASCII.GetBytes("JDWCMT01").CopyTo(decision, 0);
        header.AsSpan(16, 16).CopyTo(decision.AsSpan(8));
        byte[] decisionHash = SHA256.HashData(decision.AsSpan(0, 64));
        decisionHash.CopyTo(decision, 64);
        Assert.True(RecoveryKernel.CheckReplacementHeader(header, identity, headerHash));
        Assert.True(RecoveryKernel.CheckReplacementDecision(header, decision, decisionHash));
        for (int index = 0; index < header.Length; index++)
        {
            header[index] ^= 255;
            bool expected = index is (>= 16 and < 32) or (>= 64 and < 224);
            Assert.Equal(expected, RecoveryKernel.CheckReplacementHeader(header, identity, headerHash));
            header[index] ^= 255;
        }

        for (int index = 0; index < decision.Length; index++)
        {
            decision[index] ^= 255;
            Assert.Equal(index is >= 56 and < 64, RecoveryKernel.CheckReplacementDecision(header, decision, decisionHash));
            decision[index] ^= 255;
        }

        header.AsSpan(16, 16).Clear();
        Assert.False(RecoveryKernel.CheckReplacementHeader(header, identity, headerHash));
        for (int index = 16; index < 32; index++)
        {
            header[index] = 1;
            Assert.True(RecoveryKernel.CheckReplacementHeader(header, identity, headerHash));
            header[index] = 0;
        }

        Assert.False(RecoveryKernel.CheckReplacementHeader([], identity, headerHash));
        Assert.False(RecoveryKernel.CheckReplacementHeader(header, [], headerHash));
        Assert.False(RecoveryKernel.CheckReplacementHeader(header, identity, new byte[33]));
        Assert.False(RecoveryKernel.CheckReplacementDecision([], decision, decisionHash));
        Assert.False(RecoveryKernel.CheckReplacementDecision(header, new byte[95], decisionHash));
        Assert.False(RecoveryKernel.CheckReplacementDecision(header, decision, []));
    }

    /// <summary>Admitted bytes validate copies before bootstrap, then retain ownership through selected publication.</summary>
    /// <param name="decisionLength">A partial or complete decision suffix.</param>
    [Theory]
    [InlineData(0)]
    [InlineData(48)]
    [InlineData(96)]
    public async Task AdmittedFields_ReachBootstrapBeforeSelectedPublication(int decisionLength)
    {
        using var directory = new EvidenceDirectory();
        byte[] original = [1, 2, 3];
        byte[] replacement = [4, 5, 6, 7];
        await File.WriteAllBytesAsync(directory.Path, original, Ct);
        string stage = directory.Path + ".input.tmp";
        await File.WriteAllBytesAsync(stage, replacement, Ct);
        Assert.Throws<IOException>(() => EncryptionReplacementCommit.Commit(stage, directory.Path, phase =>
        {
            if (phase == "committed")
            {
                throw new IOException("Retain decision evidence before recovery.");
            }
        }));
        string intent = EncryptionReplacementIntent.IntentPath(directory.Path);
        byte[] bytes = await File.ReadAllBytesAsync(intent, Ct);
        if (decisionLength < 96)
        {
            Array.Resize(ref bytes, 256 + decisionLength);
            bytes.AsSpan(256).Fill(165);
            await File.WriteAllBytesAsync(intent, bytes, Ct);
        }

        File.Delete(directory.Path);
        var transitions = new List<string>();
        Assert.True(EncryptionReplacementIntent.Recover(
            directory.Path,
            phase =>
            {
                transitions.Add(phase);
                if (phase is "validated" or "publication-created")
                {
                    Assert.True(File.Exists(RecoverableWriterLock.ReceiptPath(directory.Path)));
                }
            },
            Ct));
        Assert.Contains("validation-chunk", transitions);
        Assert.Contains("publication-created", transitions);
        Assert.True(transitions.IndexOf("validation-chunk") < transitions.IndexOf("recovery-lock-created"));
        Assert.True(transitions.IndexOf("recovery-lock-created") < transitions.IndexOf("validated"));
        Assert.True(transitions.IndexOf("validated") < transitions.IndexOf("publication-created"));
        Assert.Equal(decisionLength == 96 ? replacement : original, await File.ReadAllBytesAsync(directory.Path, Ct));
        Assert.False(File.Exists(RecoverableWriterLock.ReceiptPath(directory.Path)));
        Assert.False(File.Exists(intent));
    }

    private static async Task CheckFieldConflictAsync(int offset, bool retainOwnership)
    {
        using var directory = new EvidenceDirectory();
        await File.WriteAllBytesAsync(directory.Path, [1, 2, 3], Ct);
        string stage = directory.Path + ".input.tmp";
        await File.WriteAllBytesAsync(stage, [4, 5, 6, 7], Ct);
        Assert.Throws<IOException>(() => EncryptionReplacementCommit.Commit(stage, directory.Path, phase =>
        {
            if (phase == "committed")
            {
                throw new IOException("Retain committed field evidence.");
            }
        }));
        string intent = EncryptionReplacementIntent.IntentPath(directory.Path);
        byte[] bytes = await File.ReadAllBytesAsync(intent, Ct);
        bytes[offset] ^= 255;
        if (offset < 224)
        {
            SHA256.HashData(bytes.AsSpan(0, 224)).CopyTo(bytes, 224);
        }
        else if (offset is >= 256 and < 320)
        {
            SHA256.HashData(bytes.AsSpan(256, 64)).CopyTo(bytes, 320);
        }

        await File.WriteAllBytesAsync(intent, bytes, Ct);
        if (retainOwnership)
        {
            using RecoverableWriterLock.RecoveryLease ownership = RecoverableWriterLock.AcquireRecovery(directory.Path);
        }

        Dictionary<string, string> before = Snapshot(directory.Path);
        for (int attempt = 0; attempt < 2; attempt++)
        {
            var transitions = new List<string>();
            Assert.Throws<JetCorruptDataException>(() => EncryptionReplacementIntent.Recover(directory.Path, transitions.Add, Ct));
            Assert.Empty(transitions);
            Assert.Equal(retainOwnership, File.Exists(RecoverableWriterLock.ReceiptPath(directory.Path)));
            Assert.Equal(before, Snapshot(directory.Path));
        }
    }

    private static void ReadEvidence(ObservedEvidence input, byte[] bytes)
    {
        MethodInfo method = typeof(EncryptionReplacementIntent).GetMethod("ReadEvidence", BindingFlags.NonPublic | BindingFlags.Static)!;
        try
        {
            _ = method.Invoke(null, [input, bytes]);
        }
        catch (TargetInvocationException error) when (error.InnerException is not null)
        {
            ExceptionDispatchInfo.Capture(error.InnerException).Throw();
        }
    }

    private static Dictionary<string, string> Snapshot(string path) => Directory.GetFiles(Path.GetDirectoryName(path)!)
        .Order(StringComparer.Ordinal).ToDictionary(static file => file, static file => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file))), StringComparer.Ordinal);

    private sealed class ObservedEvidence(string path, int maximumRead, int stopAfter = int.MaxValue, string failure = "eof")
        : FileStream(path, FileMode.Open, FileAccess.Read, FileShare.None)
    {
        internal int ReadCalls { get; private set; }

        public override int Read(byte[] buffer, int offset, int count)
        {
            this.ReadCalls++;
            if (this.Position >= stopAfter)
            {
                if (failure == "io")
                {
                    throw new IOException("Injected exact-evidence read failure.");
                }

                return 0;
            }

            return base.Read(buffer, offset, Math.Min(count, Math.Min(maximumRead, checked(stopAfter - (int)this.Position))));
        }
    }

    private sealed class EvidenceDirectory : IDisposable
    {
        private readonly string directory = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "jdw-replacement-fields-" + Guid.NewGuid().ToString("N"));

        internal EvidenceDirectory()
        {
            Directory.CreateDirectory(this.directory);
            this.Path = System.IO.Path.Combine(this.directory, "database.accdb");
        }

        internal string Path { get; }

        public void Dispose() => Directory.Delete(this.directory, recursive: true);
    }
}
